                                //sw.WriteLine("^GFA,9600,9600,32,");
                                //sw.WriteLine("^FT110,183");
                                //sw.WriteLine("^A0N,17,19^FD: Rs.  540.00       Rs.  180.00         Rs.  1080.00^FS");
                                sw.WriteLine("^FO24,272");
                                sw.WriteLine("^GB550,34,4^FS");
                                sw.WriteLine("^FT30,297");
                                sw.WriteLine("^A0N,25,20^FDConsumer is free to open and inspect the product before buying it^FS");


                                sw.WriteLine("^FT10,326");
