        public void ExportMRPAutomationReNormalPrint(long DCId, int Linenumber, int PrintQuantity, int Year, DateTime DCDate)
        {
            using (ATCWMS_LIVEEntities RA = new ATCWMS_LIVEEntities())
            {
                string DCMonth = DCDate.ToString("MMM");
                string DCYear = DCDate.ToString("yyyy");
                long DC = Convert.ToInt64(DCId);
                var GetMRP = CMCB.GetAutoMRPREPrint(DCId, Year).Result;
                //var print = (from c in GetMRP where c.PrinterName != "-" select c).ToList();
                var print = (from c in GetMRP.AutoMRPPrintList where c.PrinterName != "-" && c.LineNum == Linenumber select c).FirstOrDefault();
                string currentTrolleyCode = PrintQuantity.ToString();

                _FolderLocation = Path.GetDirectoryName(Application.ExecutablePath);

                string fileFullName = Path.Combine(_FolderLocation, fileName);

                if (File.Exists(fileFullName))
                {
                    File.Delete(fileFullName);
                }
                string PrinterName = print.PrinterName;
                string textBoxText = print.QULT;
                string[] lines = textBoxText.Split(new[] { Environment.NewLine }, StringSplitOptions.None);
                List<string> linesList = new List<string>(lines);

                using (StreamWriter sw = new StreamWriter(fileFullName))
                {

                    for (int k = 1; k <= PrintQuantity; k++)
                    {
                        var SNo = RA.AutoGet_MRPBatchBatch(10, 0).FirstOrDefault();
                        // Singlr LAbel
                        if (print.LabelTypeId == 1) //ATC White Large
                        {
                            sw.WriteLine("^XA");
                            sw.WriteLine("^SZ2^JMA");
                            sw.WriteLine("^MCY^PMN");
                            sw.WriteLine("^PW730");
                            sw.WriteLine("~JSN");
                            sw.WriteLine("^JZY");
                            sw.WriteLine("^LH0,0^LRN");
                            sw.WriteLine("^XZ");
                            sw.WriteLine("^XA");
                            sw.WriteLine("^FT14,44");
                            sw.WriteLine("^CI0");
                            sw.WriteLine("^A0N,24,23^FDCommodity Name:^FS");
                            int length = 183;
                            foreach (string line in linesList)
                            {
                                string[] words = line.Split(' ');

                                StringBuilder currentLine = new StringBuilder();
                                bool isFirstLine = true;

                                foreach (string word in words)
                                {

                                    if (currentLine.Length + word.Length + (currentLine.Length > 0 ? 1 : 0) <= 45)
                                    {
                                        if (currentLine.Length > 0)
                                            currentLine.Append(" ");
                                        currentLine.Append(word);
                                    }
                                    else
                                    {

                                        if (isFirstLine)
                                        {
                                            sw.WriteLine("^FT" + length + ",44");
                                            sw.WriteLine("^A0N,24,23^FD" + currentLine.ToString() + "^FS");
                                            isFirstLine = false;
                                        }
                                        else
                                        {

                                            sw.WriteLine("^FT163,65");
                                            sw.WriteLine("^A0N,24,23^FD" + currentLine.ToString() + "^FS");
                                        }

                                        length += 50;

                                        currentLine.Clear();
                                        currentLine.Append(word);
                                    }
                                }


                                if (currentLine.Length > 0)
                                {

                                    if (isFirstLine)
                                    {
                                        sw.WriteLine("^FT" + length + ",44");
                                        sw.WriteLine("^A0N,24,23^FD" + currentLine.ToString() + "^FS");
                                    }
                                    else
                                    {
                                        sw.WriteLine("^FT163,65");
                                        sw.WriteLine("^A0N,24,23^FD" + currentLine.ToString() + "^FS");
                                    }
                                }

                                length += 50;
                            }

                            sw.WriteLine("^FT14,87");
                            sw.WriteLine("^A0N,24,23^FDCommodity^FS");
                            sw.WriteLine("^FT120,87");
                            sw.WriteLine("^A0N,20,19^FD:^FS");
                            //sw.WriteLine("^FT110,87");
                            //sw.WriteLine("^A0N,17,19^FD: DHOTI,              TOWEL,            SHIRT^FS");
                            string content = print.Content.ToUpper();
                            string[] contentArray = content.Trim().Split(' ');
                            contentArray = contentArray.Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();
                            int CXPosition = 130;
                            foreach (var value in contentArray)
                            {
                                sw.WriteLine("^FT" + CXPosition + ",87");
                                sw.WriteLine("^A0N,24,23^FD" + value.Trim() + "^FS");
                                CXPosition += 175;

                            }
                            sw.WriteLine("^FT14,119");
                            sw.WriteLine("^A0N,24,23^FDSize^FS");
                            sw.WriteLine("^FT120,119");
                            sw.WriteLine("^A0N,20,19^FD:^FS");
                            //sw.WriteLine("^FT110,119");
                            //sw.WriteLine("^A0N,17,19^FD: 1.27mX2.00m    1.47mX1.80m    1.27mX2.00m^FS");


                            string Size = print.Size;
                            try
                            {
                                string[] Commodity = Regex.Split(content.Trim(), @"[,\s]+")
                          .Where(x => !string.IsNullOrWhiteSpace(x))
                          .ToArray();
                                int shirtIndex = Array.FindIndex(
                                    Commodity,
                                        c => c.Trim().ToUpper() == "SHIRT" || c.Trim().ToUpper() == "SHIRTING" || c.Trim().ToUpper() == "RM:KURTA" || c.Trim().ToUpper() == "RM:SHIRT" || c.Trim().ToUpper() == "KURTA" || c.Trim().ToUpper() == "KURTA"
                                );
                                //MessageBox.Show("Index" + shirtIndex);
                                string[] SizeArray = Size.Trim().Split(',');
                                SizeArray = SizeArray.Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();

                                int SXPosition = 130;

                                for (int i = 0; i < SizeArray.Length; i++)
                                {
                                    // MessageBox.Show("Index" + i);

                                    string value = SizeArray[i].Trim();

                                    if (shirtIndex != -1 && i == shirtIndex)
                                    {
                                        sw.WriteLine("^FT" + SXPosition + ",127");
                                        sw.WriteLine("^A0N,48,46^FD" + value + "^FS");
                                    }
                                    else
                                    {
                                        sw.WriteLine("^FT" + SXPosition + ",119");
                                        sw.WriteLine("^A0N,24,23^FD" + value + ",^FS");
                                    }

                                    SXPosition += 175;
                                }
                            }
                            catch
                            {
                                sw.WriteLine("^FT315,160");
                                sw.WriteLine("^A0N,24,23^FD " + Size.Trim() + " ^FS");
                            }
                            sw.WriteLine("^FT14,151");
                            sw.WriteLine("^A0N,24,23^FDNetQty^FS");
                            sw.WriteLine("^FT120,151");
                            sw.WriteLine("^A0N,24,23^FD:^FS");
                            string contents = print.Content;
                            string[] values = contents.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
                            var distinctValues = values.Distinct().ToList();
                            var wordCount = values.GroupBy(word => word).ToDictionary(group => group.Key, group => group.Count());
                            var adjustedWords = wordCount.Select(pair => $"{pair.Key}-{Math.Max(pair.Value - 1, 1)}N").ToList();
                            string formattedOutput = string.Join(", ", adjustedWords);
                            if (distinctValues.Count > 1)
                            {

                                try
                                {
                                    string[] SizeArray = formattedOutput.Trim().Split(' ');
                                    SizeArray = SizeArray.Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();
                                    int FXPosition = 130;

                                    foreach (var value in SizeArray)
                                    {
                                        sw.WriteLine("^FT" + FXPosition + ",151");
                                        sw.WriteLine("^A0N,24,23^FD" + value.Trim() + " ^FS");
                                        FXPosition += 175;
                                    }
                                }
                                catch
                                {
                                    sw.WriteLine("^130,151");
                                    sw.WriteLine("^A0N,24,23^FD: " + formattedOutput + " ^FS");
                                }
                            }
                            else
                            {
                                sw.WriteLine("^FT130,151");
                                sw.WriteLine("^A0N,24,23^FD" + print.boxQuantity + "N^FS");
                            }
                            sw.WriteLine("^FT14,185");
                            sw.WriteLine("^A0N,24,23^FDColour^FS");
                            sw.WriteLine("^FT120,185");
                            sw.WriteLine("^A0N,24,23^FD:^FS");
                            string color = print.color.ToUpper();
                            // string[] colorArray = color.Trim().Split(',');
                            string[] colorArray = Regex.Split(color.Trim(), @"[,]+").Where(x => !string.IsNullOrWhiteSpace(x)).ToArray();

                            colorArray = colorArray.Where(s => !string.IsNullOrWhiteSpace(s)).ToArray();

                            int CoPosition = 130;
                            foreach (var value in colorArray)
                            {

                                sw.WriteLine("^FT" + CoPosition + ",185");
                                sw.WriteLine("^A0N,24,23^FD" + value.Trim() + ",^FS");
                                CoPosition += 175;

                            }
                            sw.WriteLine("^FT86,220");
                            sw.WriteLine("^A0N,37,37^FDEXPORT QUALITY^FS");
                            if (print.cardcode == "C069071")
                            {
                                sw.WriteLine("^FT586,220");
                                sw.WriteLine("^A0N,37,37^FDASC^FS");
                            }
                            //sw.WriteLine("^FT14,275");
                            //sw.WriteLine("^A0N,20,22^FDMFG : " + DCMonth.ToUpper() + "-" + DCYear + "^FS");
                            sw.WriteLine("^^FT14,264");
                            sw.WriteLine("^A0N,20,22^FDMade in India^FS");
                            sw.WriteLine("^FT210,242");
                            sw.WriteLine("^A0N,20,22^FD" + print.SAPDocNum + "^FS");
                            sw.WriteLine("^FT190,264");
                            sw.WriteLine("^A0N,20,22^FD" + print.U_SRCode + "^FS");
                            sw.WriteLine("^FT294,242");
                            sw.WriteLine("^A0N,23,25^FD" + print.Symbol + "^FS");
                            sw.WriteLine("^FT474,242");
                            sw.WriteLine("^A0N,20,22^FD" + print.colorcode + "^FS");
                            sw.WriteLine("^FO581,227");
