        public void MRPWOAutomationRePackPrint(long WorkOrderID, int PrintQuantity, int PackQuantity)
        {
            using (ATCWMS_LIVEEntities RA = new ATCWMS_LIVEEntities())
            {
                long WorkOrderId = Convert.ToInt64(WorkOrderID);
                var print1 = (from c in RA.MRPWorkOrderDetailView(WorkOrderId) select c).FirstOrDefault();
                string currentTrolleyCode = PrintQuantity.ToString();

                _FolderLocation = Path.GetDirectoryName(Application.ExecutablePath);

                string fileFullName = Path.Combine(_FolderLocation, fileName);

                if (File.Exists(fileFullName))
                {
                    File.Delete(fileFullName);
                }
                string PrinterName = print1.PrinterName;
                using (StreamWriter sw = new StreamWriter(fileFullName))
                {
                    for (int k = 1; k <= PrintQuantity; k++)
                    {
                        var SNo = RA.AutoGet_MRPBatchBatch(10, 0).FirstOrDefault();
                        if (print1.LabelTypeId == 1) //okay
                        {
                            sw.WriteLine("< xpml >< page quantity = '0' pitch = '45.0 mm' ></ xpml > SIZE 93.7 mm, 45 mm");
                            sw.WriteLine("SPEED 8");
                            sw.WriteLine("DENSITY 9");
                            sw.WriteLine("DIRECTION 0,0");
                            sw.WriteLine("REFERENCE 0,0");
                            sw.WriteLine("OFFSET 0 mm");
                            sw.WriteLine("SET REWIND OFF");
                            sw.WriteLine("SET PEEL OFF");
                            sw.WriteLine("SET CUTTER OFF");
                            sw.WriteLine("SET PARTIAL_CUTTER OFF");
                            sw.WriteLine("< xpml ></ page ></ xpml >< xpml >< page quantity = '1' pitch = '45.0 mm' ></ xpml > SET TEAR ON");
                            sw.WriteLine("CLS");
                            sw.WriteLine("CODEPAGE 1252");
                            sw.WriteLine("TEXT 496,262,\"0\",180,11,11,\"QLTY: \"");
                            sw.WriteLine("TEXT 496,215,\"0\",180,11,11,\"SIZE: \"");
                            sw.WriteLine("TEXT 496,157,\"0\",180,11,11,\"QTY: \"");
                            sw.WriteLine("TEXT 496,109,\"0\",180,12,11,\"MFD: " + print1.WOWMonth.ToUpper() + "-" + print1.WOYear + "\"");
                            if
                            (print1.QULT.Length <= 20)
                            {
                                sw.WriteLine("TEXT 423,260,\"0\",180,11,11,\"" + print1.QULT + "\"");
                            }
                            else if (print1.QULT.Length > 20)
                            {
                                sw.WriteLine("TEXT 423,260,\"0\",180,9,11,\"" + print1.QULT + "\"");
                            }

                            sw.WriteLine("TEXT 270,160,\"0\",180,39,39,\"" + PackQuantity + "N\"");
                            sw.WriteLine("TEXT 440,215,\"0\",180,9,11,\" " + print1.Sizes + "\"");
