        public void BunldePackBarcode(string BundleBarcode, decimal Weight)
        {
            Model.CommanDB CMBC = new Model.CommanDB();
            DataSet ds = CMBC.CheckSerail(BundleBarcode);
            if (ds.Tables[0].Rows.Count != 0)
            {
                _FolderLocation = Path.GetDirectoryName(Application.ExecutablePath);
                string fileFullName = Path.Combine(_FolderLocation, fileName);
                if (File.Exists(fileFullName))
                {
                    File.Delete(fileFullName);
                }
                string PrinterName = ConfigurationManager.AppSettings["BundlePrinterName"];
                //string PrinterName = "TSC TTP-384MT";
                using (StreamWriter sw2 = new StreamWriter(fileFullName))
                {
                    sw2.WriteLine("< xpml >< page quantity = '0' pitch = '45.0 mm' ></ xpml > SIZE 93.7 mm, 45 mm");
                    sw2.WriteLine("SPEED 10");
                    sw2.WriteLine("DENSITY 14");
                    sw2.WriteLine("DIRECTION 0,0");
                    sw2.WriteLine("REFERENCE 0,0");
                    sw2.WriteLine("OFFSET 0 mm");
                    sw2.WriteLine("SET REWIND OFF");
                    sw2.WriteLine("SET PEEL OFF");
                    sw2.WriteLine("SET CUTTER OFF");
                    sw2.WriteLine("SET PARTIAL_CUTTER OFF");
                    sw2.WriteLine("< xpml ></ page ></ xpml >< xpml >< page quantity = '1' pitch = '45.0 mm' ></ xpml > SET TEAR ON");
                    sw2.WriteLine("CLS");
                    sw2.WriteLine("CODEPAGE 1252");
                    sw2.WriteLine("TEXT 2207,60,\"ROMAN.TTF\",90,1,20,\"To, \"");
                    sw2.WriteLine("TEXT 2120,74,\"ROMAN.TTF\",90,1,20,\"M/s. " + ds.Tables[0].Rows[0]["Add1"].ToString() + "\"");
                    sw2.WriteLine("TEXT 2023,74,\"0\",90,20,20,\"" + ds.Tables[0].Rows[0]["Add2"].ToString() + "\"");
                    sw2.WriteLine("TEXT 1926,74,\"0\",90,20,20,\"" + ds.Tables[0].Rows[0]["Add3"].ToString() + " \"");
                    sw2.WriteLine("TEXT 1829,74,\"0\",90,20,20,\"" + ds.Tables[0].Rows[0]["Add4"].ToString() + " \"");
                    sw2.WriteLine("TEXT 1734,74,\"0\",90,20,20,\"" + ds.Tables[0].Rows[0]["Add5"].ToString() + "\"");
                    sw2.WriteLine("TEXT 1645,74,\"0\",90,19,20,\"" + ds.Tables[0].Rows[0]["Add6"].ToString() + "\"");
                    sw2.WriteLine("TEXT 1563,74,\"0\",90,19,20,\"Mobile No. : " + ds.Tables[0].Rows[0]["Contact"].ToString() + "\"");
                    sw2.WriteLine("TEXT 1453,48,\"ROMAN.TTF\",90,1,14,\"From, \"");
                    sw2.WriteLine("TEXT 1392,48,\"ROMAN.TTF\",90,1,16,\"" + ds.Tables[0].Rows[0]["WName"].ToString() + ", \"");
                    sw2.WriteLine("TEXT 1317,48,\"ROMAN.TTF\",90,1,14,\"" + ds.Tables[0].Rows[0]["WAddr1"].ToString() + ", " + ds.Tables[0].Rows[0]["WAddr2"].ToString() + ", \"");
                    sw2.WriteLine("TEXT 1241,48,\"ROMAN.TTF\",90,1,14,\"" + ds.Tables[0].Rows[0]["WAddr3"].ToString() + " Ph. : " + ds.Tables[0].Rows[0]["WPhone"].ToString() + ".\"");

                    //Invoice No
                    sw2.WriteLine("TEXT 2345,122,\"ROMAN.TTF\",90,1,20,\"I.No : " + ds.Tables[0].Rows[0]["SAPInvDocNum"].ToString() + "/" + ds.Tables[0].Rows[0]["TotalBundle"].ToString() + "\"");

                    //Bundle No
                    sw2.WriteLine("TEXT 2375,2152,\"ROMAN.TTF\",90,1,31,\"" + ds.Tables[0].Rows[0]["LineNum"].ToString() + "/" + ds.Tables[0].Rows[0]["TotalBundle"].ToString() + "\"");

                    //Booking To
                    sw2.WriteLine("TEXT 2383,768,\"ROMAN.TTF\",90,1,15,\"Booking To :  " + ds.Tables[0].Rows[0]["U_Dsnation"].ToString() + "\"");

                    //Transport
                    sw2.WriteLine("TEXT 2295,768,\"ROMAN.TTF\",90,1,15,\"Transport : " + ds.Tables[0].Rows[0]["U_TransporterName"].ToString() + "\"");

                    //Weight
                    sw2.WriteLine("TEXT 2234,1990,\"ROMAN.TTF\",90,1,15,\"Weight : " + Weight + " Kgs.\"");

                  
                    sw2.WriteLine("QRCODE 1525,2115,L,10,A,90,M2,S7,\"" + ds.Tables[0].Rows[0]["BundleBarcode"].ToString() + "\"");
                    sw2.WriteLine("TEXT 1245,2060,\"ROMAN.TTF\",90,1,11,\"" + ds.Tables[0].Rows[0]["BundleBarcode"].ToString() + "\"");
                    sw2.WriteLine("BAR 1179,23, 5, 2433");
                    sw2.WriteLine("BAR 1083,23, 5, 2433");
                    sw2.WriteLine("BAR 23,1237, 1157, 7");
                    sw2.WriteLine("BAR 1083,23, 4, 2433");
                    sw2.WriteLine("TEXT 1151,42,\"ROMAN.TTF\",90,1,10,\"S.No\"");
                    sw2.WriteLine("TEXT 1151,284,\"ROMAN.TTF\",90,1,10,\"Item Name\"");
