                        sw2.WriteLine("TEXT " + pix + ",1150,\"ROMAN.TTF\",90,1,10,\"" + ds.Tables[1].Rows[i]["Qty"].ToString() + "\"");
                        pix = pix - 52;
                        if (i == 20)
                            break;
                    }
                    if (ds.Tables[1].Rows.Count <= 18)
                    {
                        sw2.WriteLine("TEXT " + (pix) + ",930,\"ROMAN.TTF\",90,1,10,\"Total Qty....." + ds.Tables[0].Rows[0]["Qty"].ToString() + "\"");
