                    sw2.WriteLine("TEXT 1153,2192,\"ROMAN.TTF\",90,1,10,\"MRP\"");
                    sw2.WriteLine("TEXT 1153,2372,\"ROMAN.TTF\",90,1,10,\"Qty\"");

                    pix = 1058;
                    for (; i < ds.Tables[1].Rows.Count; i++)
                    {
                        if (ds.Tables[1].Rows[i]["Dscription"].ToString().Length <= 24)
                        {
                            sw2.WriteLine("TEXT " + pix + ",1300,\"ROMAN.TTF\",90,1,10,\"" + (i + 1).ToString("00") + ". " + ds.Tables[1].Rows[i]["Dscription"].ToString() + "\"");
                        }
